#requires -Version 5.1
param([switch]$RunElectron)
$ErrorActionPreference='Stop';$studioRoot=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$repoRoot=(Resolve-Path (Join-Path $studioRoot '..')).Path;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$results=Join-Path $studioRoot ('r2-final-closure-results-'+$stamp);New-Item -ItemType Directory -Path $results|Out-Null
$head=(& git -C $repoRoot rev-parse HEAD).Trim();$base=(& git -C $repoRoot rev-parse origin/main).Trim();$start=$head;$producerPin='7792fb47c292d8f0da8a4666d174be4689ac34b3';$records=[System.Collections.Generic.List[object]]::new()
function Record([string]$id,[string]$status,[string]$command,[string]$reason,[int]$exitCode,[long]$elapsed,[string]$log){$evidenceHash=if(Test-Path -LiteralPath $log){(Get-FileHash -Algorithm SHA256 -LiteralPath $log).Hash.ToLowerInvariant()}else{''};$records.Add([pscustomobject]@{id=$id;status=$status;command=$command;reason=$reason;exit_code=$exitCode;elapsed_ms=$elapsed;base_sha=$base;head_sha=$head;evidence=$log;evidence_sha256=$evidenceHash});Write-Host "$id => $status $reason"}
function Run-Step([string]$id,[string]$command,[string]$cwd=$studioRoot){$log=Join-Path $results ($id+'.log');$watch=[Diagnostics.Stopwatch]::StartNew();Push-Location $cwd;$prior=$ErrorActionPreference;try{$ErrorActionPreference='Continue';& cmd.exe /d /s /c $command *>&1|Out-File -LiteralPath $log -Encoding utf8;$code=[int]$LASTEXITCODE;if($code -eq 0){Record $id 'PASS' $command '' $code $watch.ElapsedMilliseconds $log}else{Record $id 'FAIL' $command "exit $code" $code $watch.ElapsedMilliseconds $log}}catch{$_|Out-String|Add-Content -LiteralPath $log;Record $id 'FAIL' $command $_.Exception.Message 1 $watch.ElapsedMilliseconds $log}finally{$ErrorActionPreference=$prior;Pop-Location;$watch.Stop()}}
function Not-Run([string]$id,[string]$command,[string]$reason){$log=Join-Path $results ($id+'.log');$reason|Set-Content -LiteralPath $log;Record $id 'NOT_RUN' $command $reason 0 0 $log}

$env:FFMPEG=(& node -e "process.stdout.write(require('ffmpeg-static'))");$env:FFPROBE=(& node -e "process.stdout.write(require('@ffprobe-installer/ffprobe').path)");$env:PATH=(Split-Path -Parent $env:FFMPEG)+';'+(Split-Path -Parent $env:FFPROBE)+';'+$env:PATH
Run-Step 'C0-typecheck' 'npm.cmd run typecheck';Run-Step 'C0-lint' 'npm.cmd run lint';Run-Step 'C0-unit-contract-integration' 'npm.cmd test';Run-Step 'C0-build' 'npm.cmd run build'

$preview=$null;try{$preview=Start-Process -FilePath 'node.exe' -ArgumentList @('node_modules/vite/bin/vite.js','preview','--host','127.0.0.1','--port','4173','--strictPort') -WorkingDirectory $studioRoot -WindowStyle Hidden -PassThru;for($attempt=0;$attempt-lt 40;$attempt++){try{$response=Invoke-WebRequest -UseBasicParsing -Uri 'http://127.0.0.1:4173/' -TimeoutSec 1;if($response.StatusCode-eq 200){break}}catch{};Start-Sleep -Milliseconds 250};$browserEvidence=Join-Path $results 'browser';New-Item -ItemType Directory -Path $browserEvidence|Out-Null;$env:R1_SCREENSHOTS=$browserEvidence;$env:R2_EXTERNAL_SERVER='1';Run-Step 'C0-browser-ui' 'node node_modules/@playwright/test/cli.js test tests/ui/r1.spec.ts tests/ui/r2.spec.ts --reporter=line'}finally{Remove-Item Env:R2_EXTERNAL_SERVER -ErrorAction SilentlyContinue;Remove-Item Env:R1_SCREENSHOTS -ErrorAction SilentlyContinue;if($preview-and-not $preview.HasExited){Stop-Process -Id $preview.Id -Force}}

$baselineRoot=Join-Path $results 'core-baseline';$headRoot=Join-Path $results 'core-head';New-Item -ItemType Directory -Path $baselineRoot,$headRoot|Out-Null
& git -C $repoRoot archive $base skills/directing-stickman-videos -o (Join-Path $results 'core-base.tar');if($LASTEXITCODE-ne 0){throw 'base archive failed'};& git -C $repoRoot archive $head skills/directing-stickman-videos -o (Join-Path $results 'core-head.tar');if($LASTEXITCODE-ne 0){throw 'head archive failed'};& tar.exe -xf (Join-Path $results 'core-base.tar') -C $baselineRoot;& tar.exe -xf (Join-Path $results 'core-head.tar') -C $headRoot
$baseSkill=Join-Path $baselineRoot 'skills/directing-stickman-videos';$headSkill=Join-Path $headRoot 'skills/directing-stickman-videos';$hashReport=Join-Path $results 'core-file-hashes.json';$baseHashes=@{};Get-ChildItem -LiteralPath $baseSkill -Recurse -File|ForEach-Object{$baseHashes[$_.FullName.Substring($baseSkill.Length+1).Replace('\','/')]=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()};$headHashes=@{};Get-ChildItem -LiteralPath $headSkill -Recurse -File|ForEach-Object{$headHashes[$_.FullName.Substring($headSkill.Length+1).Replace('\','/')]=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()};[pscustomobject]@{base=$baseHashes;head=$headHashes;identical=((Compare-Object $baseHashes.GetEnumerator() $headHashes.GetEnumerator() -Property Name,Value).Count-eq 0)}|ConvertTo-Json -Depth 6|Set-Content $hashReport
Run-Step 'core-base-test' 'npm.cmd ci --no-audit --no-fund && npm.cmd test' $baseSkill;Run-Step 'core-head-test' 'npm.cmd ci --no-audit --no-fund && npm.cmd test' $headSkill
$baseRecord=$records|Where-Object id-eq 'core-base-test';$headRecord=$records|Where-Object id-eq 'core-head-test';$compareLog=Join-Path $results 'core-baseline-comparison.log';$tracked=@(& git -C $repoRoot diff --name-status "$base...$head" -- skills/directing-stickman-videos)+@(& git -C $repoRoot diff --name-status -- skills/directing-stickman-videos)+@(& git -C $repoRoot ls-files --others --exclude-standard -- skills/directing-stickman-videos);$hashesSame=((Get-Content $hashReport|ConvertFrom-Json).identical-eq $true);"BASE=$base`nHEAD=$head`nTRACKED_DIFF=$($tracked.Count)`nEXTRACTED_HASHES_IDENTICAL=$hashesSame`nBASE_EXIT=$($baseRecord.exit_code)`nHEAD_EXIT=$($headRecord.exit_code)"|Set-Content $compareLog
if($tracked.Count-ne 0-or-not $hashesSame){Record 'C0-00-core-preservation' 'FAIL' 'archive/hash/diff comparison' 'Core differs' 1 0 $compareLog}elseif($baseRecord.status-eq 'PASS'-and $headRecord.status-eq 'PASS'){Record 'C0-00-core-preservation' 'PASS' 'archive/hash/diff comparison' '' 0 0 $compareLog}elseif($baseRecord.exit_code-eq $headRecord.exit_code){Record 'C0-00-core-preservation' 'BASELINE_FAIL' 'archive/hash/diff comparison' 'Same original Core fails identically by exit status on base and head; see both logs' $headRecord.exit_code 0 $compareLog}else{Record 'C0-00-core-preservation' 'FAIL' 'archive/hash/diff comparison' 'NEW_R2_REGRESSION: base/head outcomes differ' $headRecord.exit_code 0 $compareLog}

Run-Step 'C0-09-offline-native' ('node scripts/r2-offline-native.mjs `"'+$results+'`"')
$producerRoot=if($env:VOICE_STUDIO_ROOT){$env:VOICE_STUDIO_ROOT}else{Join-Path $repoRoot '.producer-audit'};if((Test-Path (Join-Path $producerRoot 'lite/chatterbox_assembly.py'))-and ((& git -C $producerRoot rev-parse HEAD).Trim()-eq $producerPin)){Run-Step 'C0-02-producer-longform' 'python -m pytest tests/chatterbox/test_final_closure_v2.py tests/chatterbox/test_resume_integrity_v3.py -q' $producerRoot}else{Not-Run 'C0-02-producer-longform' 'producer source-owned tests' "Set VOICE_STUDIO_ROOT to producer commit $producerPin"}
if($RunElectron){$oldElectronNode=$env:ELECTRON_RUN_AS_NODE;Remove-Item Env:ELECTRON_RUN_AS_NODE -ErrorAction SilentlyContinue;$env:R2_ELECTRON_PROJECT=Join-Path $results 'native-fixture';try{Run-Step 'C0-10-real-electron' 'npx.cmd playwright test --config playwright.electron.config.ts --reporter=line'}finally{Remove-Item Env:R2_ELECTRON_PROJECT -ErrorAction SilentlyContinue;if($null-ne $oldElectronNode){$env:ELECTRON_RUN_AS_NODE=$oldElectronNode}}}else{Not-Run 'C0-10-real-electron' 'Playwright Electron production/dev/e2e' 'Pass -RunElectron on an interactive Windows desktop'}
$contractLog=Join-Path $results 'voice-settings-contract.log';$matches=@(& rg -n -i 'contract' src/renderer/features/settings src/renderer/pages);if($matches.Count-eq 0){'Contract UI absent; default 3901 is main-owned.'|Set-Content $contractLog;Record 'C0-14-settings' 'PASS' 'UI grep plus persisted endpoint tests' '' 0 0 $contractLog}else{$matches|Set-Content $contractLog;Record 'C0-14-settings' 'FAIL' 'UI grep' 'Contract text remains in Settings' 1 0 $contractLog}

$c1=@('C1-01 Nano GTX1650 live short','C1-02 Nano GTX1650 live long/resume','C1-03 authorized paid ElevenLabs live','C1-04 owner watches/approves real project','C1-05 owner visual parity review');foreach($item in $c1){Not-Run ($item.Split(' ')[0]) 'owner acceptance' ($item.Substring(6)+' requires owner hardware/account/consent/review')}
$summary=[ordered]@{schema='r2-final-closure-evidence-v2';base_main_sha=$base;start_head_sha=$start;final_head_sha=$head;voice_producer_sha=$producerPin;created_at=(Get-Date).ToString('o');steps=$records;overall=if($records.status-contains 'FAIL'){'FAIL'}elseif($records.status-contains 'NOT_RUN'){'CODE_CLOSED_LIVE_NOT_RUN'}else{'PASS'}};$summary|ConvertTo-Json -Depth 9|Set-Content -LiteralPath (Join-Path $results 'results.json') -Encoding utf8
$zip=Join-Path $studioRoot ('r2-final-closure-results-'+$stamp+'.zip');Compress-Archive -LiteralPath $results -DestinationPath $zip;Write-Host "Evidence: $zip";if($records.status-contains 'FAIL'){exit 1}
